function longestMirror(s: string): string {
  const n = s.length;
  const isMirror = (i: number, j: number) => { while (i < j) if (s[i++] !== s[j--]) return false; return true; };
  let start = 0, len = 1;
  for (let i = 0; i < n; i++)
    for (let j = i + len; j < n; j++) // only slices longer than the best
      if (isMirror(i, j)) { start = i; len = j - i + 1; }
  return s.slice(start, start + len);
}

