function longestMirror(s: string): string {
  const n = s.length;
  let start = 0, len = 1;
  const grow = (lo: number, hi: number) => {
    while (lo >= 0 && hi < n && s[lo] === s[hi]) { lo--; hi++; }
    const L = hi - lo - 1; // mirror is s[lo + 1 .. hi - 1]
    if (L > len) { start = lo + 1; len = L; }
  };
  for (let c = 0; c < n; c++) {
    grow(c, c);     // odd length, centre on a letter
    grow(c, c + 1); // even length, centre between letters
  }
  return s.slice(start, start + len);
}

