    def longestMirror(self, s: str) -> str:
        n = len(s)
        start, length = 0, 1
        for c in range(n):
            for lo, hi in ((c, c), (c, c + 1)):  # odd centre, even centre
                while lo >= 0 and hi < n and s[lo] == s[hi]:
                    lo -= 1
                    hi += 1
                if hi - lo - 1 > length:
                    start, length = lo + 1, hi - lo - 1
        return s[start:start + length]

