function longestMirror(s) {
  const n = s.length;
  let start = 0, len = 1;
  const grow = (lo, hi) => {
    while (lo >= 0 && hi < n && s[lo] === s[hi]) {
      lo--;
      hi++;
    }
    const L = hi - lo - 1;
    if (L > len) {
      start = lo + 1;
      len = L;
    }
  };
  for (let c = 0; c < n; c++) {
    grow(c, c);
    grow(c, c + 1);
  }
  return s.slice(start, start + len);
}
